$body = @{username="admin"; password="admin123"} | ConvertTo-Json; $res = Invoke-RestMethod -Uri http://localhost:5045/api/Auth/login -Method Post -ContentType "application/json" -Body $body; $token = $res.data; $parts = $token.Split("."); if ($parts.Length -ge 2) { $payload = $parts[1]; while ($payload.Length % 4 -ne 0) { $payload += "=" }; [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($payload)) }
